package com.aryaa.sdm.config;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.userdetails.User; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.provisioning.InMemoryUserDetailsManager; import org.springframework.security.web.*; import org.springframework.security.web.util.matcher.AntPathRequestMatcher; import org.springframework.web.cors.*; import java.util.List;
@Configuration @EnableWebSecurity public class SecurityConfig {
 @Value("${sdm.admin.username}") private String user; @Value("${sdm.admin.password}") private String pass; @Value("${cors.allowed-origins}") private String[] origins;
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean InMemoryUserDetailsManager userDetailsService(PasswordEncoder e){UserDetails u=User.withUsername(user).password(e.encode(pass)).roles("OPERATOR").build();return new InMemoryUserDetailsManager(u);}
 @Bean CorsConfigurationSource corsConfigurationSource(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of(origins));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("*"));c.setAllowCredentials(false);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/api/**",c);return s;}
 @Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{return http.cors(x->x.configurationSource(corsConfigurationSource())).csrf(x->x.disable()).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.GET,"/api/**").permitAll().requestMatchers("/api/events","/actuator/health","/h2-console/**").permitAll().requestMatchers(HttpMethod.POST,"/api/**").authenticated().requestMatchers(HttpMethod.PUT,"/api/**").authenticated().requestMatchers(HttpMethod.DELETE,"/api/**").authenticated().anyRequest().permitAll()).httpBasic(Customizer.withDefaults()).exceptionHandling(x->x.authenticationEntryPoint(new JsonAuthenticationEntryPoint())).headers(x->x.frameOptions(f->f.sameOrigin())).build();}
}